import numpy as np
import math

def private_count(data, epsilon, rng):
    n = len(data)
    if n == 0:
        return 0.0
    count = sum(data)
    q = (math.exp(epsilon) + 1) / (math.exp(epsilon) + math.exp(-epsilon))
    if rng.binomial(1, q):
        count += 1
    if count > n:
        count = n
    return count / n

