import numpy as np
import math

def private_argmax(data, epsilon, rng):
    if not data:
        return None

    counts = {'A': 0, 'B': 0, 'C': 0, 'D': 0}
    for label in data:
        counts[label] += 1

    n = len(data)
    delta = 1 / n
    alpha = (epsilon - delta) / 2
    beta = epsilon - alpha

    noisy_counts = {k: v + rng.laplace(0, beta / n) for k, v in counts.items()}

    max_count = max(noisy_counts.values())
    candidates = [k for k, v in noisy_counts.items() if v == max_count]

    if len(candidates) > 1:
        return rng.choice(candidates)
    else:
        return candidates[0]

